{"code":"// 分别看基期和本期的汇总: 净销售额和投放额(contribution)
const base = data.filter(d => d.period === '基期');
const current = data.filter(d => d.period === '本期');

const sumBase = {net_sales: base.reduce((s,d)=>s+d.net_sales_cents,0), contribution: base.reduce((s,d)=>s+d.contribution_cents,0)};
const sumCurrent = {net_sales: current.reduce((s,d)=>s+d.net_sales_cents,0), contribution: current.reduce((s,d)=>s+d.contribution_cents,0)};

result = {
  基期: sumBase,
  本期: sumCurrent,
  净销售额变化: ((sumCurrent.net_sales - sumBase.net_sales)/sumBase.net_sales * 100).toFixed(2) + '%',
  投放额变化: ((sumCurrent.contribution - sumBase.contribution)/sumBase.contribution * 100).toFixed(2) + '%',
  基期ROI: (sumBase.net_sales / sumBase.contribution).toFixed(2),
  本期ROI: (sumCurrent.net_sales / sumCurrent.contribution).toFixed(2)
};"}

